const tabs = [...document.querySelectorAll('.tab')];
const panels = [...document.querySelectorAll('.panel')];
const chips = [...document.querySelectorAll('.chip')];
const searchInput = document.querySelector('#query');
const searchButton = document.querySelector('#search-button');
const seeMore = document.querySelector('.see-more');
const morePanel = document.querySelector('.more-panel');
const photoSlides = [...document.querySelectorAll('.slide')];
const photoCount = document.querySelector('#photoCount');
const prevPhoto = document.querySelector('#prevPhoto');
const nextPhoto = document.querySelector('#nextPhoto');
const cardTitle = document.querySelector('#cardTitle');
const speciesData = { axolotl: { title: 'Axolotl', label: 'Amphibian', info: 'Mexico' }, newt: { title: 'Newt', label: 'Amphibian', info: 'Cool streams' }, salamander: { title: 'Salamander', label: 'Amphibian', info: 'Forest floor' }, frog: { title: 'Frog', label: 'Amphibian', info: 'Ponds' }, 'aquatic-plants': { title: 'Aquarium plants', label: 'Habitat', info: 'Water garden' } };
let photoIndex = 0;
const setTab = (targetTab) => { tabs.forEach((tab) => { const active = tab.dataset.tab === targetTab; tab.classList.toggle('is-selected', active); tab.setAttribute('aria-selected', String(active)); tab.tabIndex = active ? 0 : -1; }); panels.forEach((panel) => { const active = panel.id === `panel-${targetTab}`; panel.classList.toggle('is-visible', active); panel.hidden = !active; }); };
const setPhoto = (index) => { photoIndex = (index + photoSlides.length) % photoSlides.length; photoSlides.forEach((slide, i) => slide.classList.toggle('active', i === photoIndex)); photoCount.textContent = `${photoIndex + 1} / ${photoSlides.length}`; };
const rerenderSpecies = (key) => { const species = speciesData[key]; if (!species) return; cardTitle.textContent = species.title; document.querySelector('.kicker').textContent = species.label; document.querySelector('.badge').textContent = species.info; chips.forEach((chip) => chip.classList.toggle('is-selected', chip.dataset.species === key)); };
const renderSearch = (query) => { const normalized = query.toLowerCase(); const results = { axolotl: 'Axolotl', newt: 'Newt', salamander: 'Salamander', frog: 'Frog', aquarium: 'Aquarium plants' }; const name = results[normalized] || 'Axolotl'; cardTitle.textContent = name; document.querySelector('.kicker').textContent = normalized.includes('plant') ? 'Habitat' : 'Amphibian'; };
searchButton.addEventListener('click', () => renderSearch(searchInput.value.trim() || 'axolotl'));
searchInput.addEventListener('keydown', (event) => { if (event.key === 'Enter') renderSearch(searchInput.value.trim() || 'axolotl'); });
tabs.forEach((tab) => { tab.addEventListener('click', () => setTab(tab.dataset.tab)); tab.addEventListener('keydown', (event) => { if (event.key !== 'ArrowRight' && event.key !== 'ArrowLeft') return; event.preventDefault(); const currentIndex = tabs.indexOf(tab); const nextIndex = event.key === 'ArrowRight' ? (currentIndex + 1) % tabs.length : (currentIndex - 1 + tabs.length) % tabs.length; tabs[nextIndex].focus(); setTab(tabs[nextIndex].dataset.tab); }); });
chips.forEach((chip) => chip.addEventListener('click', () => rerenderSpecies(chip.dataset.species)));
seeMore.addEventListener('click', () => { const expanded = seeMore.getAttribute('aria-expanded') === 'true'; seeMore.setAttribute('aria-expanded', String(!expanded)); morePanel.hidden = expanded; });
prevPhoto.addEventListener('click', () => setPhoto(photoIndex - 1));
nextPhoto.addEventListener('click', () => setPhoto(photoIndex + 1));
setTab('overview');
setPhoto(0);
